#!/bin/sh
# Applies NativeTavern's engine patches to the vendored upstream core.
#
# Why a patch instead of a fork: upstream SillyTavern is vendored unmodified.
# The only change the app needs is to skip Webpack at launch — a phone should
# not run a bundler on every cold start, and the bundle is shipped in the app.
#
# Every patch below is regenerated by Scripts/sync-core.sh, so this script is
# the record of what differs from upstream. Run it after syncing the core.
set -eu

CORE_DIR="${1:-$(cd "$(dirname "$0")/../Engine" && pwd)/core}"

python3 - "$CORE_DIR" <<'PY'
import sys
from pathlib import Path

core = Path(sys.argv[1])
target = core / "src/middleware/webpack-serve.js"
source = target.read_text(encoding="utf-8")

MARKER = "// NativeTavern: use the prebuilt bundle shipped with the app."
if MARKER in source:
    print("webpack-serve.js already patched")
    raise SystemExit(0)

original = """    devMiddleware.runWebpackCompiler = ({ forceDist = false, pruneCache = false } = {}) => {
        console.log();
        console.log('Compiling frontend libraries...');
"""

replacement = """    devMiddleware.runWebpackCompiler = ({ forceDist = false, pruneCache = false } = {}) => {
        // NativeTavern: use the prebuilt bundle shipped with the app.
        // The bundle is produced once by Scripts/build-lib-bundle.sh and is
        // byte-identical in purpose to what this compiler would emit.
        const prebuilt = path.join(serverDirectory, 'public/lib.bundle.js');
        if (fs.existsSync(prebuilt)) {
            console.log('Using prebuilt frontend libraries.');
            return Promise.resolve();
        }

        console.log();
        console.log('Compiling frontend libraries...');
"""

if original not in source:
    raise SystemExit("webpack-serve.js did not match the expected upstream shape")

source = source.replace(original, replacement)

# The patch needs fs and serverDirectory imports that upstream does not have here.
# Webpack is only needed when there is no prebuilt bundle. Keeping it as a
# static import would load the bundler on every start, defeating the point.
if "import webpack from 'webpack';" in source:
    source = source.replace(
        "import webpack from 'webpack';\n",
        "// Webpack is imported lazily in runWebpackCompiler.\n",
        1,
    )
    source = source.replace(
        "    devMiddleware.runWebpackCompiler = ({ forceDist = false, pruneCache = false } = {}) => {",
        "    devMiddleware.runWebpackCompiler = async ({ forceDist = false, pruneCache = false } = {}) => {",
        1,
    )
    source = source.replace(
        "        const publicLibConfig = getPublicLibConfig({ forceDist, pruneCache });\n        const compiler = webpack(publicLibConfig);",
        "        const publicLibConfig = getPublicLibConfig({ forceDist, pruneCache });\n        const { default: webpack } = await import('webpack');\n        const compiler = webpack(publicLibConfig);",
        1,
    )

if "import fs from 'node:fs';" not in source:
    source = source.replace(
        "import path from 'node:path';",
        "import fs from 'node:fs';\nimport path from 'node:path';\nimport { serverDirectory } from '../server-directory.js';",
        1,
    )

target.write_text(source, encoding="utf-8")
print("patched", target)

# webpack.config.js is imported at startup whether or not a build runs, and
# pulls the bundler in with it. Its only use is a cache-version key, which the
# prebuilt bundle does not need.
config = core / "webpack.config.js"
config_source = config.read_text(encoding="utf-8")
if "import webpack from 'webpack';" in config_source:
    config_source = config_source.replace(
        "import webpack from 'webpack';\n",
        "// NativeTavern: webpack is not imported at startup; see getWebpackCacheVersion.\n",
        1,
    )
    config_source = config_source.replace(
        "webpack.version",
        "(globalThis.NT_WEBPACK_VERSION ?? 'unknown')",
        1,
    )
    if "(globalThis.NT_WEBPACK_VERSION" in config_source:
        config_source = config_source.replace(
            "import isDocker from 'is-docker';",
            "import isDocker from 'is-docker';\n\n// NativeTavern: the bundle is prebuilt, so the bundler version is not read here.\nglobalThis.NT_WEBPACK_VERSION = 'unused-with-prebuilt-bundle';",
            1,
        )
    config.write_text(config_source, encoding="utf-8")
    print("patched", config)
PY
